(function(){
var R=document.documentElement,$=function(s){return document.querySelector(s)},$$=function(s){return[].slice.call(document.querySelectorAll(s))};
R.classList.add('js');
var stick=$('#stick'),xr=$('#xray');
var IM={"n": "data:image/png;base64,", "s": "data:image/png;base64,", "e": "data:image/png;base64,", "d1": "data:image/png;base64,", "d2": "data:image/png;base64,", "m": "data:image/png;base64,", "o": "data:image/png;base64,", "a": "data:image/png;base64,"};
function E(x){x=Math.max(0,Math.min(1,x));return x*x*(3-2*x)}
var MX=0,bg=[],K=['n','s','e','a','m','o'];
$$('.fl').forEach(function(el){el.style.width=el.dataset.w+'px';el.innerHTML='<img alt="" src="'+IM[el.dataset.i]+'">'});
// persistent floating cell field (the photo cutouts, parallax with scroll + mouse)
(function(){var h=$('#bgc'),n=innerWidth<720?8:13;for(var i=0;i<n;i++){var d=.25+Math.random()*.75,e=document.createElement('img');
 e.src=IM[K[i%K.length]];e.alt='';e.style.width=(70+d*150)+'px';e.style.opacity=(.14+d*.3).toFixed(2);h.appendChild(e);
 bg.push({e:e,d:d,x:Math.random(),y:Math.random(),p:Math.random()*6.28})}})();
// hero: the real mitosis stages crossfade as you scroll, then split in two
var FR=['n','s','e','a','d1','d2'];
(function(){var h='';FR.forEach(function(k){h+='<img alt="" src="'+IM[k]+'">'});h+='<img alt="" src="'+IM.m+'"><img alt="" src="'+IM.m+'">';$('#mit').innerHTML=h})();
function mit(r,m){var cs=r.offsetWidth,im=r.children,pos=m*6.4,i,w;
 for(i=0;i<6;i++){w=Math.max(0,1-Math.abs(pos-i));if(i==5)w=pos>5?Math.max(0,1-(pos-5)):w;im[i].style.opacity=E(w).toFixed(3);im[i].style.transform='scale('+(1+.03*Math.sin(m*9+i))+')'}
 w=E(Math.min(1,Math.max(0,pos-5)));var d=.62*cs+E((m-.88)/.12)*.35*cs;
 im[6].style.opacity=im[7].style.opacity=w.toFixed(3);
 im[6].style.transform='translateY('+(-d-cs/2)+'px)';im[7].style.transform='translateY('+(d-cs/2)+'px)'}
// project cards: each card shows one stage from the reference
$$('.sh').forEach(function(el){var k=+el.closest('.card').style.getPropertyValue('--i');el.innerHTML='<img alt="" src="'+IM[['n','s','e','d1'][k]]+'">'});
xr.appendChild($('.layer.base').cloneNode(true));
function mv(cx,cy){
 var r=stick.getBoundingClientRect(),x=cx-r.left,y=cy-r.top;
 [stick,xr].forEach(function(e){e.style.setProperty('--x',x+'px');e.style.setProperty('--y',y+'px')});
 MX=(cx/innerWidth-.5)*2;R.style.setProperty('--mx',((cx/innerWidth-.5)*2).toFixed(3));R.style.setProperty('--my',((cy/innerHeight-.5)*2).toFixed(3));
 
 var c=$('#cx');c.style.setProperty('--px',cx+'px');c.style.setProperty('--py',cy+'px');c.classList.toggle('on',cy>=r.top&&cy<=r.bottom);
}
addEventListener('pointermove',function(e){mv(e.clientX,e.clientY)});
mv(innerWidth/2,innerHeight/2);
var scenes=$$('.scene'),cards=$$('.card'),bar=$('#bar'),last=scrollY,v=0,wc=$('#wc');
function loop(){
 scenes.forEach(function(s){
  var r=s.getBoundingClientRect(),p=Math.min(1,Math.max(0,-r.top/(r.height-innerHeight)));
  s.style.setProperty('--p',p.toFixed(4));
  if(s.id==='hero'){var mm=Math.max(0,Math.min(1,(p-.4)/.55)),mo=Math.max(0,Math.min(1,(p-.38)*6));$$('.mit').forEach(function(r){r.style.opacity=mo;mit(r,mm)})}
  if(s.id==='works'){
   cards.forEach(function(c,i){
    var z=i*-1000-600+p*3000,o=Math.min(1,Math.max(0,(z+2600)/900))*Math.min(1,Math.max(0,(1000-z)/450));
    c.style.opacity=o.toFixed(3);c.style.pointerEvents=o>.6?'auto':'none';
   });
   wc.textContent='0'+Math.min(4,Math.floor(p*3.6)+1);
  }
 });
 var tt=performance.now()/1000,Hh=innerHeight+400;
 bg.forEach(function(o){var y=(((o.y*Hh-scrollY*o.d*.45)%Hh)+Hh)%Hh-200,x=o.x*innerWidth+MX*o.d*50+Math.sin(tt*.5+o.p)*18;o.e.style.transform='translate3d('+x+'px,'+(y+Math.sin(tt*.7+o.p)*14)+'px,0) rotate('+Math.sin(tt*.3+o.p)*10+'deg)'});
 v+=((scrollY-last)/50-v)*.15;last=scrollY;
 R.style.setProperty('--v',Math.max(-1,Math.min(1,v)).toFixed(3));
 bar.style.transform='scaleX('+(scrollY/(R.scrollHeight-innerHeight||1))+')';
 requestAnimationFrame(loop);
}
loop();
cards.forEach(function(c){
 var x=c.querySelector('.xr');
 c.addEventListener('pointermove',function(e){var r=c.getBoundingClientRect();
  x.style.setProperty('--cx',(e.clientX-r.left)+'px');x.style.setProperty('--cy',(e.clientY-r.top)+'px')});
});
var io=new IntersectionObserver(function(es){es.forEach(function(e){
 var on=e.isIntersecting;
 [].slice.call(e.target.querySelectorAll('.rv')).forEach(function(el,i){
  el.style.transitionDelay=on?(i*.15)+'s':'0s';el.classList.toggle('on',on);
 });
})},{rootMargin:'-25% 0px -25% 0px',threshold:0});
$$('.sec').forEach(function(el){io.observe(el)});
// profile card: tap / Enter flips it (hover does it on desktop)
$$('.pt').forEach(function(c){function t(){c.classList.toggle('flip')}c.addEventListener('click',t);c.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();t()}})});
// services: each row unfolds in place (one at a time); click again or the ↑ to fold
var sxs=$$('.sx');
function fold(x,open){
 sxs.forEach(function(y){var o=y===x&&open;y.classList.toggle('open',o);y.querySelector('.sv').setAttribute('aria-expanded',o)});
 if(open)setTimeout(function(){var t=x.getBoundingClientRect().top;if(t<90||t>innerHeight*.45)scrollBy({top:t-100,behavior:'smooth'})},780);
 else{var t=x.getBoundingClientRect().top;if(t<0)scrollBy({top:t-90,behavior:'smooth'})}}
sxs.forEach(function(x){var r=x.querySelector('.sv');
 r.addEventListener('click',function(){fold(x,!x.classList.contains('open'))});
 r.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();fold(x,!x.classList.contains('open'))}});
 x.querySelector('.sp-up').addEventListener('click',function(){fold(x,false);r.focus({preventScroll:true})})});
// project detail panel
var PJ=[
 {t:'프로젝트 이름 A',c:'브랜드 아이덴티티',y:'2026',r:'Art Direction · Identity',tl:'Illustrator · Figma',cl:'Client Name',a:'n',b:'s',d:'프로젝트 한 줄 소개를 여기에 적어주세요. 어떤 문제를 풀었고 어떤 결과를 만들었는지 짧고 분명하게 설명합니다.',st:[['배경','프로젝트를 시작한 이유와 목표를 적어주세요.'],['과정','리서치, 컨셉, 시안 등 진행 과정을 적어주세요.'],['결과','최종 결과물과 성과를 적어주세요.']]},
 {t:'프로젝트 이름 B',c:'웹 디자인',y:'2026',r:'UI/UX · Web Design',tl:'Figma · Webflow',cl:'Client Name',a:'s',b:'e',d:'프로젝트 한 줄 소개를 여기에 적어주세요. 사용자에게 어떤 경험을 주고 싶었는지 설명합니다.',st:[['배경','프로젝트를 시작한 이유와 목표를 적어주세요.'],['과정','리서치, 와이어프레임, 인터랙션 설계 과정을 적어주세요.'],['결과','최종 결과물과 성과를 적어주세요.']]},
 {t:'프로젝트 이름 C',c:'모션 · 3D',y:'2025',r:'Motion · 3D',tl:'Blender · After Effects',cl:'Client Name',a:'e',b:'d1',d:'프로젝트 한 줄 소개를 여기에 적어주세요. 움직임으로 전달하고 싶었던 메시지를 설명합니다.',st:[['배경','프로젝트를 시작한 이유와 목표를 적어주세요.'],['과정','스토리보드, 모델링, 렌더링 과정을 적어주세요.'],['결과','최종 결과물과 성과를 적어주세요.']]},
 {t:'프로젝트 이름 D',c:'일러스트',y:'2025',r:'Illustration',tl:'Procreate · Illustrator',cl:'Client Name',a:'d1',b:'d2',d:'프로젝트 한 줄 소개를 여기에 적어주세요. 어떤 스타일과 이야기를 담았는지 설명합니다.',st:[['배경','프로젝트를 시작한 이유와 목표를 적어주세요.'],['과정','스케치, 컬러, 완성까지의 과정을 적어주세요.'],['결과','최종 결과물과 성과를 적어주세요.']]}];
var pd=$('#pd'),pw=$('#pd-w'),cur=0;
function show(i){cur=(i+PJ.length)%PJ.length;var q=PJ[cur],nx=PJ[(cur+1)%PJ.length],pv=PJ[(cur+PJ.length-1)%PJ.length];
 $('#pd-n').textContent='0'+(cur+1)+' / 0'+PJ.length;
 pw.innerHTML='<h1>'+q.t+'</h1>'+
  '<div class="pd-meta"><div><span>분야</span><b>'+q.c+'</b></div><div><span>연도</span><b>'+q.y+'</b></div><div><span>역할</span><b>'+q.r+'</b></div><div><span>도구</span><b>'+q.tl+'</b></div><div><span>클라이언트</span><b>'+q.cl+'</b></div></div>'+
  '<p class="lead">'+q.d+'</p>'+
  '<div class="pd-fig"><img alt="" src="'+IM[q.a]+'"><small>이미지 1 — 실제 작업물로 교체해 주세요</small></div>'+
  '<div class="pd-fig"><img alt="" src="'+IM[q.b]+'"><small>이미지 2</small></div>'+
  '<div class="pd-cols">'+q.st.map(function(x){return '<div><h4>'+x[0]+'</h4><p>'+x[1]+'</p></div>'}).join('')+'</div>'+
  '<div class="pd-nav"><button data-d="-1">← '+pv.t+'</button><button data-d="1">'+nx.t+' →</button></div>';
 [].forEach.call(pw.children,function(e,k){e.style.transitionDelay=(.3+k*.06)+'s'});pd.scrollTop=0}
function openP(i){show(i);R.classList.add('lock');pd.classList.add('open')}
function closeP(){pd.classList.remove('open');R.classList.remove('lock')}
$$('.card .fa').forEach(function(f){f.insertAdjacentHTML('beforeend','<div class="go">자세히 보기 →</div>')});
cards.forEach(function(c){c.addEventListener('click',function(){openP(+c.style.getPropertyValue('--i'))})});
$('#pd-x').addEventListener('click',closeP);
pw.addEventListener('click',function(e){var b=e.target.closest('button[data-d]');if(b){pd.scrollTop=0;show(cur+(+b.dataset.d))}});
addEventListener('keydown',function(e){if(!pd.classList.contains('open'))return;
 if(e.key==='Escape')closeP();if(e.key==='ArrowRight')show(cur+1);if(e.key==='ArrowLeft')show(cur-1)});
(function(){
 var I=$('#intro');
 if(matchMedia('(prefers-reduced-motion:reduce)').matches){I.remove();R.classList.add('ready');return}
 if('scrollRestoration' in history)history.scrollRestoration='manual';
 scrollTo(0,0);R.classList.add('lock');
 var ic=$('#ic'),ip=$('#ip'),h='',t0=0,T=3800,opened=0,skip=0,lt=0;
 // double-click (or double-tap) skips the intro
 function sk(){if(!opened)skip=1}
 addEventListener('dblclick',sk,true);
 // own timing check so it works regardless of OS double-click settings (mouse, trackpad, touch)
 document.addEventListener('pointerdown',function(){var n=Date.now();if(n-lt<500)sk();lt=n},true);
 FR.concat(['m','m']).forEach(function(k){h+='<img alt="" src="'+IM[k]+'">'});ic.innerHTML=h;
 function f(now){
  if(!t0)t0=now;if(skip)t0=now-T-300;var t=now-t0,m=Math.min(1,t/T);
  ic.style.opacity=Math.min(1,t/400);mit(ic,m);ip.textContent=('00'+Math.round(m*100)).slice(-3);
  if(t>=T+300){opened=1;I.classList.add('open');var im=ic.children;
   im[6].style.transition=im[7].style.transition='top 1s cubic-bezier(.7,0,.2,1)';
   im[6].style.top='calc(50% - 70vh)';im[7].style.top='calc(50% + 70vh)';
   setTimeout(function(){R.classList.add('ready')},350);
   setTimeout(function(){I.remove();R.classList.remove('lock')},1300)}
  if(!opened)requestAnimationFrame(f)}
 requestAnimationFrame(f);
})();
})();
